// Extraction des messages reçus via Meta Graph Webhook
const body = $json.body || $json;

if (body.object !== 'instagram') {
  return [];
}

const entries = body.entry || [];
const results = [];

for (const entry of entries) {
  const messaging = entry.messaging || [];
  for (const event of messaging) {
    const senderId = event.sender?.id;
    const messageText = (event.message?.text || '').trim();
    const quickReplyPayload = event.message?.quick_reply?.payload;

    if (senderId && (messageText || quickReplyPayload)) {
      const normalized = (messageText || quickReplyPayload).toUpperCase();
      const isKeyword = ['CALMI', 'DODO', 'HISTOIRE', 'CONTE', 'ACCES', 'ACCÈS', 'SOMMEIL', 'RELAX'].some(k => normalized.includes(k));

      results.push({
        senderId,
        messageText,
        isKeyword,
        timestamp: event.timestamp
      });
    }
  }
}

return results.map(r => ({ json: r }));

